import requests
from rest_framework import viewsets, status
from rest_framework.response import Response
from .enum import MockEndpointsEnum

class MockItemViewSet(viewsets.ModelViewSet):
    """
    Override list() to fan out to two upstream APIs
    and merge responses on a shared key.
    """
    queryset = []          # required by ModelViewSet
    serializer_class = None

    def list(self, request, *args, **kwargs):
        try:
            r1 = requests.get(MockEndpointsEnum.ORDERS_API.value, timeout=5)
            r2 = requests.get(MockEndpointsEnum.PRODUCTS_API.value, timeout=5)

            if r1.status_code != 200 or r2.status_code != 200:
                return Response(
                    {'error': 'Upstream service unavailable'},
                    status=status.HTTP_502_BAD_GATEWAY
                )

            orders   = {item['customer_id']: item for item in r1.json()}
            products = {item['customer_id']: item for item in r2.json()}

            merged = [
                {**orders[key], **products[key]}
                for key in orders
                if key in products
            ]

            return Response(merged, status=status.HTTP_200_OK)

        except requests.exceptions.RequestException as exc:
            return Response(
                {'error': str(exc)},
                status=status.HTTP_503_SERVICE_UNAVAILABLE
            )

from concurrent.futures import ThreadPoolExecutor, as_completed
import requests

def fetch(url: str) -> list:
    resp = requests.get(url, timeout=5)
    resp.raise_for_status()
    return resp.json()

def parallel_fetch(urls: list[str]) -> list:
    results = {}
    with ThreadPoolExecutor(max_workers=len(urls)) as pool:
        futures = {pool.submit(fetch, url): url for url in urls}
        for future in as_completed(futures):
            results[futures[future]] = future.result()
    return results

